import { normalizeRotation, type PdfEditPage } from "./edit";
import { defaultExportFilename, sanitizePdfFilename } from "./export";
import { MAX_PAGE_RANGES, parsePageRanges, splitEveryPages } from "./page-ranges";
import { MAX_PDF_FILES, MAX_PDF_FILE_BYTES, MAX_PDF_PAGES, PdfUserError, type PdfFileEntry, type PdfPageInfo } from "./types";

export const MAX_PLAN_INPUT_BYTES = 128 * 1024 ** 2;
export const MAX_PLAN_TOTAL_PAGES = 1000;
export const MAX_PLAN_OUTPUT_PAGES = 1000;
export const MAX_PLAN_OUTPUTS = MAX_PAGE_RANGES;
/** Cumulative generated bytes, enforced by the executor because plans contain no bytes. */
export const MAX_PLAN_OUTPUT_BYTES = 100 * 1024 ** 2;

export interface PdfPlanSource {
  readonly documentId: string;
  readonly name: string;
  readonly size: number;
  readonly originalPages: readonly PdfPageInfo[];
}
export interface PdfOutputDefinition {
  readonly id: string;
  readonly fileName: string;
  readonly rangeLabel: string;
  readonly pages: readonly PdfEditPage[];
}
export interface PdfOutputPlan {
  readonly mode: "selection" | "merge" | "split" | "current";
  readonly sources: readonly PdfPlanSource[];
  readonly outputs: readonly PdfOutputDefinition[];
}
export type PdfSplitOptions = { kind: "ranges"; ranges: string } | { kind: "every"; every: number };

function invalid(): never { throw new PdfUserError("输出计划或页面来源无效，请重新选择文档与页面。"); }
const nonempty = (value: unknown): value is string => typeof value === "string" && !!value.trim();
const quarterTurn = (value: number) => Number.isSafeInteger(value) && value % 90 === 0;
function keys(value: unknown, allowed: readonly string[]) {
  if (typeof value !== "object" || value === null || Array.isArray(value) ||
    Reflect.ownKeys(value).some((key) => typeof key !== "string" || !allowed.includes(key))) invalid();
}

/** Validate bindings and limits without renaming, reordering or truncating a plan. */
export function validateOutputPlan(plan: PdfOutputPlan): void {
  try {
    keys(plan, ["mode", "sources", "outputs"]);
    if (!["selection", "merge", "split", "current"].includes(plan.mode) || !Array.isArray(plan.sources) || !Array.isArray(plan.outputs)) invalid();
    if (!plan.sources.length || plan.sources.length > MAX_PDF_FILES || !plan.outputs.length || plan.outputs.length > MAX_PLAN_OUTPUTS) {
      throw new PdfUserError("输出计划最多使用 20 个来源文档并生成 50 份 PDF。");
    }
    if ((plan.mode === "merge" ? plan.sources.length < 2 : plan.sources.length !== 1) ||
      (plan.mode !== "split" && plan.outputs.length !== 1)) invalid();
    const sources = new Map<string, PdfPlanSource>();
    let inputBytes = 0;
    for (const source of plan.sources) {
      keys(source, ["documentId", "name", "size", "originalPages"]);
      if (!nonempty(source.documentId) || !nonempty(source.name) || sources.has(source.documentId) ||
        !Number.isSafeInteger(source.size) || source.size < 1 || source.size > MAX_PDF_FILE_BYTES ||
        !Array.isArray(source.originalPages) || !source.originalPages.length || source.originalPages.length > MAX_PDF_PAGES) invalid();
      inputBytes += source.size;
      for (const [index, page] of source.originalPages.entries()) {
        keys(page, ["number", "width", "height", "rotation", "orientation"]);
        if (page.number !== index + 1 || !quarterTurn(page.rotation) ||
          ![page.width, page.height].every((value) => Number.isFinite(value) && value > 0 && value <= 144_000) ||
          page.orientation !== (page.width === page.height ? "square" : page.width > page.height ? "landscape" : "portrait")) invalid();
      }
      sources.set(source.documentId, source);
    }
    if (inputBytes > MAX_PLAN_INPUT_BYTES) throw new PdfUserError("一次输出任务的来源文件累计不能超过 128 MiB，请减少参与文件。");
    const outputIds = new Set<string>();
    const fileNames = new Set<string>();
    const pageIds = new Set<string>();
    const usedSources = new Map<string, Set<number>>();
    let outputPages = 0;
    for (const output of plan.outputs) {
      keys(output, ["id", "fileName", "rangeLabel", "pages"]);
      if (!nonempty(output.id) || outputIds.has(output.id) || !nonempty(output.fileName) ||
        sanitizePdfFilename(output.fileName) !== output.fileName || fileNames.has(output.fileName.toLowerCase()) ||
        !nonempty(output.rangeLabel) || !Array.isArray(output.pages) || !output.pages.length) invalid();
      if (output.pages.length > MAX_PLAN_OUTPUT_PAGES) throw new PdfUserError("单份输出最多包含 1000 页，请减少页面。");
      outputIds.add(output.id); fileNames.add(output.fileName.toLowerCase());
      outputPages += output.pages.length;
      for (const page of output.pages) {
        keys(page, ["id", "sourceDocumentId", "sourcePageNumber", "originalRotation", "rotationDelta"]);
        const source = sources.get(page.sourceDocumentId);
        const original = source?.originalPages[page.sourcePageNumber - 1];
        if (!nonempty(page.id) || pageIds.has(page.id) || !source || !Number.isSafeInteger(page.sourcePageNumber) || !original ||
          !quarterTurn(page.originalRotation) || !quarterTurn(page.rotationDelta) ||
          normalizeRotation(page.originalRotation) !== normalizeRotation(original.rotation)) invalid();
        const pages = usedSources.get(source.documentId) ?? new Set<number>();
        if (pages.has(page.sourcePageNumber)) throw new PdfUserError("输出页面不能重复；拆分结果之间也不能包含重复页面。");
        pages.add(page.sourcePageNumber); usedSources.set(source.documentId, pages); pageIds.add(page.id);
      }
    }
    if (outputPages > MAX_PLAN_TOTAL_PAGES) throw new PdfUserError("一次输出任务累计最多包含 1000 页，请减少页面或来源文档。");
    if (usedSources.size !== sources.size) invalid();
  } catch (error) {
    if (error instanceof PdfUserError) throw error;
    invalid();
  }
}

const copyInfo = (page: PdfPageInfo): PdfPageInfo => ({ number: page.number, width: page.width, height: page.height, rotation: page.rotation, orientation: page.orientation });
const copyPage = (page: PdfEditPage): PdfEditPage => ({ id: page.id, sourceDocumentId: page.sourceDocumentId,
  sourcePageNumber: page.sourcePageNumber, originalRotation: page.originalRotation, rotationDelta: page.rotationDelta });

/** A plan owns metadata only; no reference to mutable editor state survives. */
export function snapshotOutputPlan(plan: PdfOutputPlan): PdfOutputPlan {
  validateOutputPlan(plan);
  return Object.freeze({ mode: plan.mode,
    sources: Object.freeze(plan.sources.map((source) => Object.freeze({ documentId: source.documentId, name: source.name, size: source.size,
      originalPages: Object.freeze(source.originalPages.map((page) => Object.freeze(copyInfo(page)))) }))),
    outputs: Object.freeze(plan.outputs.map((output) => Object.freeze({ id: output.id, fileName: output.fileName, rangeLabel: output.rangeLabel,
      pages: Object.freeze(output.pages.map((page) => Object.freeze(copyPage(page)))) }))),
  });
}

function ready(entry: PdfFileEntry) {
  try {
    if (!entry || entry.status !== "ready" || !entry.edit || !Array.isArray(entry.edit.present?.pages) || !entry.edit.present.pages.length ||
      !Array.isArray(entry.pages)) throw new PdfUserError("请先选择已完成解析且保留页面的 PDF。");
    if (!nonempty(entry.id) || !nonempty(entry.name)) invalid();
    return { source: { documentId: entry.id, name: entry.name, size: entry.size, originalPages: entry.pages.map(copyInfo) },
      pages: entry.edit.present.pages.map(copyPage) };
  } catch (error) {
    if (error instanceof PdfUserError) throw error;
    invalid();
  }
}

function label(numbers: readonly number[]): string {
  const ranges: string[] = [];
  for (let index = 0; index < numbers.length; index++) {
    const start = numbers[index];
    let end = start;
    while (numbers[index + 1] === end + 1) end = numbers[++index];
    ranges.push(start === end ? `${start}` : `${start}-${end}`);
  }
  return ranges.join(", ");
}

function output(pages: readonly PdfEditPage[], fileName: string, rangeLabel: string, index = 0): PdfOutputDefinition {
  return { id: `output-${index + 1}`, fileName: sanitizePdfFilename(fileName), rangeLabel, pages };
}

export function buildCurrentPlan(entry: PdfFileEntry, fileName?: string): PdfOutputPlan {
  const current = ready(entry);
  return snapshotOutputPlan({ mode: "current", sources: [current.source], outputs: [output(current.pages,
    fileName ?? defaultExportFilename(entry.name), label(current.pages.map((_, index) => index + 1)))] });
}

export function buildSelectionPlan(entry: PdfFileEntry, fileName?: string): PdfOutputPlan {
  const current = ready(entry);
  const ids = entry.edit!.present.selectedIds;
  if (!Array.isArray(ids) || !ids.length) throw new PdfUserError("请先选择至少一页再导出。");
  const selected = new Set(ids);
  if (selected.size !== ids.length || ids.some((id) => !current.pages.some((page) => page.id === id))) invalid();
  const numbers = current.pages.flatMap((page, index) => selected.has(page.id) ? [index + 1] : []);
  const pages = current.pages.filter((page) => selected.has(page.id));
  const stem = Array.from(sanitizePdfFilename(entry.name).slice(0, -4)).slice(0, 111).join("");
  return snapshotOutputPlan({ mode: "selection", sources: [current.source],
    outputs: [output(pages, fileName ?? `${stem}_selected.pdf`, label(numbers))] });
}

export function buildMergePlan(files: readonly PdfFileEntry[], orderedDocumentIds: readonly string[], fileName = "merged.pdf"): PdfOutputPlan {
  if (!Array.isArray(files) || !Array.isArray(orderedDocumentIds) || orderedDocumentIds.length < 2) {
    throw new PdfUserError("请至少选择两个已解析的 PDF 进行合并。");
  }
  if (orderedDocumentIds.length > MAX_PDF_FILES || new Set(orderedDocumentIds).size !== orderedDocumentIds.length) invalid();
  const ordered = orderedDocumentIds.map((id) => {
    const matches = files.filter((entry) => entry.id === id);
    if (matches.length !== 1) invalid();
    return ready(matches[0]);
  });
  return snapshotOutputPlan({ mode: "merge", sources: ordered.map((entry) => entry.source),
    outputs: [output(ordered.flatMap((entry) => entry.pages), fileName, `合并 ${ordered.length} 个文档`)] });
}

export function buildSplitPlan(entry: PdfFileEntry, split: PdfSplitOptions, fileNamePrefix?: string): PdfOutputPlan {
  const current = ready(entry);
  if (!split || (split.kind !== "ranges" && split.kind !== "every")) invalid();
  const ranges = split.kind === "ranges" ? parsePageRanges(split.ranges, current.pages.length) : splitEveryPages(current.pages.length, split.every);
  const stem = Array.from(sanitizePdfFilename(fileNamePrefix ?? entry.name).slice(0, -4)).slice(0, 112).join("");
  return snapshotOutputPlan({ mode: "split", sources: [current.source], outputs: ranges.map((range, index) =>
    output(current.pages.slice(range.start - 1, range.end), `${stem}_part-${String(index + 1).padStart(2, "0")}.pdf`, range.label, index)) });
}
